using System.Text.Json;
using Microsoft.EntityFrameworkCore;
using Npgsql;
using VHEI.Application;
using VHEI.Domain;
using VHEI.Infrastructure;
namespace VHEI.Api;
public static partial class ExaminationEndpoints
{
    private static void MapMarks(RouteGroupBuilder routes)
    {
        routes.MapPut("/{id:guid}/marks",async(Guid institutionId,Guid id,MarksRequest r,HttpContext ctx,ErpDbContext db)=>
        {
            if(r.Items==null||r.Items.Length is <1 or >1000||r.Items.Any(x=>x==null)||r.Items.Select(x=>x.StudentId).Distinct().Count()!=r.Items.Length)return Results.Problem("Provide the complete distinct saved roster.",statusCode:400);
            await using var tx=await db.Database.BeginTransactionAsync();var exam=await Lock(db,institutionId,id);if(exam==null)return Results.NotFound();if(!await Allowed(ctx,db,exam))return Results.Problem("Assessment is not assigned to you.",statusCode:403);if(exam.Status!="Draft"||exam.Version!=r.Version)return Results.Problem("Assessment is locked or changed.",statusCode:409);
            var marks=await db.ExamMarks.Where(x=>x.InstitutionId==institutionId&&x.AssessmentId==id).ToListAsync();if(!marks.Select(x=>x.StudentId).ToHashSet().SetEquals(r.Items.Select(x=>x.StudentId)))return Results.Problem("Marks must match the saved assessment roster exactly.",statusCode:400);
            if(r.Items.Any(x=>x.Attendance is not("Unentered" or "Present" or "Absent")||(x.Attendance=="Present"&&(x.InternalMark==null||x.ExternalMark==null))||(x.Attendance!="Present"&&(x.InternalMark!=null||x.ExternalMark!=null))||(x.InternalMark!=null&&(!Precise(x.InternalMark.Value)||x.InternalMark<0||x.InternalMark>exam.MaximumInternal))||(x.ExternalMark!=null&&(!Precise(x.ExternalMark.Value)||x.ExternalMark<0||x.ExternalMark>exam.MaximumExternal))))return Results.Problem("Use Unentered/Absent with empty marks, or Present with both component marks within configured limits.",statusCode:400);
            var input=r.Items.ToDictionary(x=>x.StudentId);foreach(var row in marks){var value=input[row.StudentId];row.Attendance=value.Attendance;row.InternalMark=value.InternalMark;row.ExternalMark=value.ExternalMark;}exam.Version++;Audit(db,ctx,institutionId,"MarksSaved",id,$"Draft marks saved for {marks.Count} roster members.");await db.SaveChangesAsync();await tx.CommitAsync();return Results.Ok(new{exam.Version});
        });
        routes.MapPost("/{id:guid}/submit",async(Guid institutionId,Guid id,ArchiveRequest r,HttpContext ctx,ErpDbContext db)=>
        {
            if(!Text(r.Reason,3,500))return Results.Problem("Provide a marks submission note.",statusCode:400);await using var tx=await db.Database.BeginTransactionAsync();var exam=await Lock(db,institutionId,id);if(exam==null)return Results.NotFound();if(!await Allowed(ctx,db,exam))return Results.Problem("Assessment is not assigned to you.",statusCode:403);if(exam.Status!="Draft"||exam.Version!=r.Version)return Results.Problem("Assessment changed or already submitted.",statusCode:409);if(exam.ScheduledOn>DateOnly.FromDateTime(DateTime.UtcNow.AddMinutes(330)))return Results.Problem("Marks cannot be submitted before the scheduled assessment date.",statusCode:400);if(await db.ExamMarks.AnyAsync(x=>x.InstitutionId==institutionId&&x.AssessmentId==id&&x.Attendance=="Unentered"))return Results.Problem("Enter every saved roster member before submission.",statusCode:400);exam.Status="Submitted";exam.SubmittedBy=ctx.Actor();exam.Version++;exam.ReviewNote=r.Reason.Trim();Audit(db,ctx,institutionId,"MarksSubmitted",id,r.Reason.Trim());await db.SaveChangesAsync();await tx.CommitAsync();return Results.Ok(new{exam.Version,exam.Status});
        });
        routes.MapPost("/{id:guid}/approve",async(Guid institutionId,Guid id,ArchiveRequest r,HttpContext ctx,ErpDbContext db)=>
        {
            if(!Text(r.Reason,3,500))return Results.Problem("Provide a result approval note.",statusCode:400);await using var tx=await db.Database.BeginTransactionAsync();var exam=await Lock(db,institutionId,id);if(exam==null)return Results.NotFound();if(exam.Status!="Submitted"||exam.Version!=r.Version)return Results.Problem("Assessment changed or not submitted.",statusCode:409);if(exam.SubmittedBy==ctx.Actor())return Results.Problem("Another administrator must approve submitted results.",statusCode:403);
            var policy=await db.GradingPolicies.SingleAsync(x=>x.InstitutionId==institutionId&&x.Id==exam.GradingPolicyId);if(policy.Status!="Approved")return Results.Problem("Grading policy is not approved.",statusCode:409);var bands=JsonSerializer.Deserialize<GradeBand[]>(policy.BandsJson)!;var marks=await db.ExamMarks.Where(x=>x.InstitutionId==institutionId&&x.AssessmentId==id).ToListAsync();foreach(var mark in marks){var result=ResultCalculator.Calculate(exam,mark,bands,policy.FailGrade);mark.Total=result.Total;mark.Percentage=result.Percentage;mark.IsPass=result.IsPass;mark.Grade=result.Grade;mark.GradePoints=result.GradePoints;}exam.Status="Approved";exam.ApprovedBy=ctx.Actor();exam.ReviewNote=r.Reason.Trim();exam.Version++;Audit(db,ctx,institutionId,"ResultsApproved",id,r.Reason.Trim());await db.SaveChangesAsync();await tx.CommitAsync();return Results.Ok(new{exam.Version,exam.Status});
        }).RequireAuthorization("Manage");
        routes.MapPost("/{id:guid}/publish",async(Guid institutionId,Guid id,ArchiveRequest r,HttpContext ctx,ErpDbContext db)=>
        {
            if(!Text(r.Reason,3,500))return Results.Problem("Provide a publication note.",statusCode:400);await using var tx=await db.Database.BeginTransactionAsync();var exam=await Lock(db,institutionId,id);if(exam==null)return Results.NotFound();if(exam.Status!="Approved"||exam.Version!=r.Version||exam.ApprovedBy==null)return Results.Problem("Only current independently approved results can be published.",statusCode:409);var marks=await db.ExamMarks.Where(x=>x.InstitutionId==institutionId&&x.AssessmentId==id).ToListAsync();foreach(var m in marks)m.IsPublished=true;exam.Status="Published";exam.PublishedBy=ctx.Actor();exam.PublishedAt=DateTime.UtcNow;exam.Version++;Audit(db,ctx,institutionId,"ResultsPublished",id,r.Reason.Trim());try{await db.SaveChangesAsync();}catch(DbUpdateException e)when(e.InnerException is PostgresException{SqlState:PostgresErrorCodes.UniqueViolation}){return Results.Problem("A student already has a published result for this subject. No duplicate result was published.",statusCode:409);}await tx.CommitAsync();return Results.Ok(new{exam.Version,exam.Status});
        }).RequireAuthorization("Manage");
    }
    internal static async Task<object> Transcript(ErpDbContext db,Guid institution,Guid student)
    {
        var rows=await(from m in db.ExamMarks join e in db.ExamAssessments on new{m.InstitutionId,Id=m.AssessmentId} equals new{e.InstitutionId,e.Id} join s in db.Subjects on new{m.InstitutionId,Id=m.SubjectId} equals new{s.InstitutionId,s.Id} join p in db.Programmes on new{s.InstitutionId,Id=s.ProgrammeId} equals new{p.InstitutionId,p.Id} join session in db.AcademicSessions on new{s.InstitutionId,Id=s.AcademicSessionId} equals new{session.InstitutionId,session.Id} where m.InstitutionId==institution&&m.StudentId==student&&m.IsPublished&&e.Status=="Published" orderby s.Semester,s.Code select new{assessmentId=e.Id,subjectId=s.Id,s.Code,subject=s.Name,s.ProgrammeId,programme=p.Name,s.AcademicSessionId,session=session.Name,s.Semester,e.Credits,m.Attendance,m.Total,m.Percentage,m.Grade,m.GradePoints,m.IsPass,e.PublishedAt}).ToListAsync();
        var semesters=rows.GroupBy(x=>new{x.ProgrammeId,x.AcademicSessionId,x.Semester,x.programme,x.session}).Select(g=>new{g.Key.ProgrammeId,g.Key.AcademicSessionId,g.Key.Semester,g.Key.programme,g.Key.session,credits=g.Sum(x=>x.Credits),sgpa=ResultCalculator.Gpa(g.Select(x=>(x.Credits,x.GradePoints??0))),backlogs=g.Count(x=>!x.IsPass)}).ToList();
        var cumulative=rows.GroupBy(x=>new{x.ProgrammeId,x.programme}).Select(g=>new{g.Key.ProgrammeId,g.Key.programme,credits=g.Sum(x=>x.Credits),cgpa=ResultCalculator.Gpa(g.Select(x=>(x.Credits,x.GradePoints??0))),backlogs=g.Count(x=>!x.IsPass)}).ToList();return new{results=rows,semesters,cumulative,note="GPA covers only published assessments recorded here. Full curriculum, retakes and graduation eligibility require separate approved policies."};
    }
}
